 ("table", ["Point", "Detail"], [["Title", "Fire and Ice"], ["Poet", "Robert Frost (American)"], ["Form", "Short lyric of nine lines in one stanza"], ["Rhyme scheme", "abaabcbcb"], ["Voice", "First person: 'I', speaking from experience"], ["Symbols", "Fire = desire (greed, passion); Ice = hate (coldness, cruelty)"], ["Tone", "Calm, thoughtful, ironic"], ["Theme", "Human passions can be as destructive as any natural catastrophe"]]),
